<?php
require_once __DIR__ . '/../../includes/config.php';
require_once __DIR__ . '/../../includes/auth_check.php';
require_once __DIR__ . '/../../includes/functions.php';
if (($_SESSION['user_role'] ?? '') !== 'system_manager') { header('Location: ' . BASE_URL . '/index.php'); exit; }
$backupDirectory = __DIR__ . '/../../assets/backups';
if (!is_dir($backupDirectory)) { mkdir($backupDirectory, 0755, true); }
function recoverySqlIdentifier($value) { return '`' . str_replace('`', '``', (string)$value) . '`'; }
function recoverySqlLiteral($value) { if ($value === null) return 'NULL'; return getDBConnection()->quote((string)$value); }
function getRecoveryTables() {
    return array_column(fetchAll("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_TYPE = 'BASE TABLE' ORDER BY CREATE_TIME, TABLE_NAME"), 'TABLE_NAME');
}
function createRecoverySnapshot($tables) {
    $output = "-- PrototypeDO MySQL snapshot generated " . date('Y-m-d H:i:s') . "\n\n";
    foreach ($tables as $table) {
        $columns = fetchAll("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = ? ORDER BY ORDINAL_POSITION", [$table]);
        if (!$columns) continue;
        $names = array_column($columns, 'COLUMN_NAME');
        $quotedTable = recoverySqlIdentifier($table);
        foreach (fetchAll('SELECT * FROM ' . $quotedTable) as $row) {
            $values = [];
            foreach ($names as $name) $values[] = recoverySqlLiteral($row[$name] ?? null);
            $quotedColumns = implode(', ', array_map('recoverySqlIdentifier', $names));
            $output .= 'INSERT INTO ' . $quotedTable . ' (' . $quotedColumns . ') VALUES (' . implode(', ', $values) . ");\n";
        }
        $output .= "\n";
    }
    return $output;
}
function splitRecoveryStatements($contents) {
    $statements = [];
    $current = '';
    $inString = false;
    $length = strlen($contents);
    for ($index = 0; $index < $length; $index++) {
        $character = $contents[$index];
        $current .= $character;
        if ($character === "'" && ($index === 0 || $contents[$index - 1] !== '\\')) {
            $inString = !$inString;
        } elseif ($character === ';' && !$inString) {
            $statements[] = substr($current, 0, -1);
            $current = '';
        }
    }
    if (trim($current) !== '') $statements[] = $current;
    return $statements;
}
function restoreRecoverySnapshot($contents) {
    if (stripos($contents, 'PrototypeDO MySQL snapshot generated') === false) {
        throw new RuntimeException('This file is not a PrototypeDO MySQL snapshot generated by this page.');
    }

    $statements = splitRecoveryStatements($contents);
    $allowedTables = array_fill_keys(getRecoveryTables(), true);
    $restoreStatements = [];
    foreach ($statements as $statement) {
        $statement = trim(preg_replace('/^--.*(?:\r\n|\r|\n|$)/m', '', $statement));
        if ($statement === '') continue;
        if (!preg_match('/^INSERT\s+INTO\s+`([^`]+)`\s*\(/i', $statement, $match)) {
            throw new RuntimeException('The backup contains an unsupported SQL statement. Only backups generated by this page can be imported.');
        }
        if (!isset($allowedTables[$match[1]])) {
            throw new RuntimeException('The backup contains an unknown table: ' . $match[1]);
        }
        $restoreStatements[] = $statement;
    }
    if (!$restoreStatements) throw new RuntimeException('The backup does not contain any data to restore.');

    $pdo = getDBConnection();
    $pdo->beginTransaction();
    try {
        $pdo->exec('SET FOREIGN_KEY_CHECKS = 0');
        foreach (array_keys($allowedTables) as $table) {
            $pdo->exec('DELETE FROM ' . recoverySqlIdentifier($table));
        }
        foreach ($restoreStatements as $statement) $pdo->exec($statement);
        $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
        $pdo->commit();
    } catch (Throwable $e) {
        if ($pdo->inTransaction()) $pdo->rollBack();
        $pdo->exec('SET FOREIGN_KEY_CHECKS = 1');
        throw $e;
    }
    return count($restoreStatements);
}
$message = null; $error = null;
try {
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $action = $_POST['action'] ?? '';
        if ($action === 'getSystemMetrics' && ($_POST['ajax'] ?? '') === '1') {
            $databaseSize = fetchValue("SELECT ROUND(SUM(data_length + index_length) / 1024 / 1024, 2) FROM information_schema.tables WHERE table_schema = DATABASE()");
            $activeSessions = fetchValue("SELECT COUNT(*) FROM users WHERE is_active = 1 AND last_login >= DATE_SUB(NOW(), INTERVAL 30 MINUTE)");
            $auditEventsToday = fetchValue("SELECT COUNT(*) FROM audit_log WHERE timestamp >= CURRENT_DATE");
            $failedLoginCount = fetchValue("SELECT COUNT(*) FROM audit_log WHERE action = 'Failed Login'");
            $totalEvents = fetchValue("SELECT COUNT(*) FROM audit_log");
            $failedLogins = fetchAll("SELECT ip_address, timestamp, JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.username')) AS attempted_username, JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.reason')) AS reason FROM audit_log WHERE action = 'Failed Login' ORDER BY timestamp DESC LIMIT 10");
            foreach ($failedLogins as &$failedLogin) {
                $failedLogin['timestamp'] = formatDatabaseDateTime($failedLogin['timestamp']);
            }
            unset($failedLogin);
            $peakHours = fetchAll("SELECT HOUR(timestamp) AS hour_of_day, COUNT(*) AS activity_count FROM audit_log WHERE timestamp >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY HOUR(timestamp) ORDER BY activity_count DESC LIMIT 5");
            header('Content-Type: application/json');
            echo json_encode(['success' => true, 'metrics' => compact('databaseSize', 'activeSessions', 'auditEventsToday', 'failedLoginCount', 'totalEvents', 'failedLogins', 'peakHours')]);
            exit;
        } elseif ($action === 'toggle_maintenance' && ($_POST['ajax'] ?? '') === '1') {
            $maintenanceMode = ($_POST['enabled'] ?? '') === '1' ? 'enabled' : 'disabled';
            setSystemSetting('maintenance_mode', $maintenanceMode);
            logAudit($_SESSION['user_id'] ?? null, 'Maintenance Mode Toggled', 'system_settings', null, null, [
                'value' => $maintenanceMode
            ]);
            header('Content-Type: application/json');
            echo json_encode(['success' => true, 'enabled' => getSystemSetting('maintenance_mode') === 'enabled']);
            exit;
        } elseif ($action === 'save_maintenance') {
            $maintenanceMode = isset($_POST['maintenance_mode']) ? 'enabled' : 'disabled';
            setSystemSetting('maintenance_mode', $maintenanceMode);
            logAudit($_SESSION['user_id'] ?? null, 'Maintenance Mode Updated', 'system_settings', null, null, [
                'value' => $maintenanceMode
            ]);
            $message = 'Maintenance mode setting saved.';
        } elseif ($action === 'download_backup') {
            $filename = 'PrototypeDO_snapshot_' . date('Ymd_His') . '.sql';
            $path = $backupDirectory . DIRECTORY_SEPARATOR . $filename;
            $snapshot = createRecoverySnapshot(getRecoveryTables());
            if (file_put_contents($path, $snapshot, LOCK_EX) === false) {
                throw new RuntimeException('The backup file could not be created.');
            }
            $history = json_decode(getSystemSetting('backup_history', '[]'), true) ?: [];
            array_unshift($history, ['filename' => $filename, 'created_at' => date('Y-m-d H:i:s'), 'size' => filesize($path)]);
            setSystemSetting('backup_history', json_encode(array_slice($history, 0, 25)));
            logAudit($_SESSION['user_id'] ?? null, 'Database Backup Created', 'system_backup', null, null, [
                'filename' => $filename,
                'size' => filesize($path)
            ]);
            header('Content-Type: application/sql');
            header('Content-Disposition: attachment; filename="' . $filename . '"');
            header('Content-Length: ' . filesize($path));
            readfile($path);
            exit;
        } elseif ($action === 'import_backup') {
            if (getSystemSetting('maintenance_mode', 'disabled') !== 'enabled') {
                throw new RuntimeException('Enable system maintenance mode before importing a backup.');
            }
            if (!isset($_FILES['backup_file']) || $_FILES['backup_file']['error'] !== UPLOAD_ERR_OK) {
                throw new RuntimeException('Select a valid .sql backup file to import.');
            }
            if (($_FILES['backup_file']['size'] ?? 0) > 50 * 1024 * 1024) {
                throw new RuntimeException('The backup file must be 50 MB or smaller.');
            }
            if (!isset($_POST['confirm_restore'])) {
                throw new RuntimeException('Confirm that the current database should be replaced before importing.');
            }
            $contents = file_get_contents($_FILES['backup_file']['tmp_name']);
            if ($contents === false) throw new RuntimeException('The backup file could not be read.');
            $statementCount = restoreRecoverySnapshot($contents);
            logAudit($_SESSION['user_id'] ?? null, 'Database Backup Imported', 'system_backup', null, null, [
                'filename' => basename($_FILES['backup_file']['name']),
                'statements' => $statementCount
            ]);
            $message = 'Backup imported successfully. ' . $statementCount . ' data statements restored.';
        }
    }
} catch (Throwable $e) { $error = $e->getMessage(); }
$maintenanceEnabled = getSystemSetting('maintenance_mode', 'disabled') === 'enabled';
$history = json_decode(getSystemSetting('backup_history', '[]'), true) ?: [];
$historyPage = max(1, (int)($_GET['backup_page'] ?? 1));
$historyPerPage = 7;
$historyPages = max(1, (int)ceil(count($history) / $historyPerPage));
$historyPage = min($historyPage, $historyPages);
$historyEntries = array_slice($history, ($historyPage - 1) * $historyPerPage, $historyPerPage);
$pageTitle = 'Data Recovery'; $adminName = getFormattedUserName();
?>
